def skill():
    ds = set()
    for i in range(1, 6):
        for j in range(1, 6):
            k = 2*j - i
            if k != 0:
                ds.add(Rational(5, k))
    tot = 0
    for d in ds:
        X = {-5 + (i - 2)*d for i in range(1, 6)}
        Y = {-10 + 2*(j - 1)*d for j in range(1, 6)}
        if len(X & Y) == 3:
            tot += -5 + 18*d
    return tot

def standard():
    d = Symbol('d')
    def a(n):
        return -5 + (n - 2)*d
    cand = set()
    for i in range(1, 6):
        for j in range(1, 6):
            yj = a(j) + a(j + 2)
            for s in solve(Eq(a(i), yj), d):
                if s != 0:
                    cand.add(s)
    tot = 0
    for s in cand:
        X = {simplify(a(i).subs(d, s)) for i in range(1, 6)}
        Y = {simplify((a(j) + a(j + 2)).subs(d, s)) for j in range(1, 6)}
        if len(X & Y) == 3:
            tot += a(20).subs(d, s)
    return tot

def unique():
    return [standard()]
